  wallLine(g, 2, 25, 13, 25, 5, 7, "inner", { open: [[7, 5, 25, 7, 6, 25], [12, 5, 25, 12, 6, 25]] });
  wallLine(g, 2, 25, 13, 25, 9, 11, "inner", { open: [[12, 9, 25, 12, 10, 25]] });
