  wallLine(g, 11, 10, 13, 10, 9, 11, "inner", { open: [[12, 9, 10, 12, 10, 10]] });

  // ---- stairs (E20 long run along x13, E21 down to the garage) and banisters, into air only.
  stairFlight(g, 13, 13, 5, 3, "south", DARK_OAK_STAIRS);
