  // (12,13,19) is not a banister: it is the only way off the top stair head (the landing cell (13,12,20) is a hole).
  for (const [x, y, z] of [[12, 5, 16], [12, 5, 17], [12, 9, 13], [12, 9, 14], [12, 9, 15]]) {
    putAir(g, x, y, z, ...B.fence("dark_oak"));
